APXF["za-bonnievale"] = {"lede": "A ward around Bonnievale on the Breede River, known for dairy and wine co-operatives.", "facts": [["Category", "WO"], ["Recognized", ""], ["Main grapes", "Chardonnay, Colombard, Sauvignon Blanc, Shiraz, Cabernet Sauvignon"]], "sections": [["The place", "<p>Robertson's wards share its lime-rich soils and warm, dry, wind-cooled climate.</p>"], ["The rules", "<p>A Wine of Origin production area. South Africa's Wine of Origin scheme came into force in 1973 and now operates under the Liquor Products Act of 1989, administered by the Wine and Spirit Board. The law defines a hierarchy of geographical units (such as Western Cape), regions, districts and wards, plus registered single vineyards; overarching units such as Cape Coast and Greater Cape allow blends across regions. A ward must have a clear influence of soil, climate and ecology on the wine, and its name must reflect a real geographic feature. 'Wine of Origin' with an area name guarantees that 100% of the grapes come from that area; a variety or vintage on the label requires 85%. The certification seal on the bottle confirms that the claims were checked and the wine passed tasting. The scheme sets no rules on grapes, yields or style. This is a ward, the smallest level below a single vineyard.</p>"], ["In the glass", "<p>Chardonnay and sparkling Cap Classique from lime-rich soils; Shiraz, Cabernet; Colombar.</p>"], ["For the exam", "<p>Ward in the Robertson district, Breede River Valley region.</p>"]], "producers": [], "sources": [["Wines of South Africa: Wine of Origin scheme", "https://www.wosa.co.za/The-Industry/Wines-Of-Origin/Wine-Of-Origin-scheme"], ["Wine Certification Authority: What we do", "https://wineauthority.org/what-we-do"], ["SAWIS: Wine of Origin Scheme (Liquor Products Act 60 of 1989), updated 2025", "https://www.sawis.co.za/winelaw/download/Wine_of_Origin_Scheme,_updated_05_2025.pdf"]], "checked": "2026-11-14"};
APXF["za-breede-river-valley"] = {"lede": "The inland region of the Breedekloof, Worcester and Robertson districts, warm and irrigated, the source of a large share of South Africa's wine and brandy.", "facts": [["Category", "WO"], ["Recognized", ""], ["Main grapes", "Chenin Blanc, Colombard, Chardonnay, Shiraz"]], "sections": [["The place", "<p>The region crushes a large share of South Africa's grapes, most of it through co-operative cellars.</p>"], ["The rules", "<p>A Wine of Origin production area. South Africa's Wine of Origin scheme came into force in 1973 and now operates under the Liquor Products Act of 1989, administered by the Wine and Spirit Board. The law defines a hierarchy of geographical units (such as Western Cape), regions, districts and wards, plus registered single vineyards; overarching units such as Cape Coast and Greater Cape allow blends across regions. A ward must have a clear influence of soil, climate and ecology on the wine, and its name must reflect a real geographic feature. 'Wine of Origin' with an area name guarantees that 100% of the grapes come from that area; a variety or vintage on the label requires 85%. The certification seal on the bottle confirms that the claims were checked and the wine passed tasting. The scheme sets no rules on grapes, yields or style.</p>"], ["In the glass", "<p>Chenin Blanc, Colombar, Chardonnay and value reds; brandy and fortified Muscadel.</p>"], ["For the exam", "<p>WO unit, Breede River Valley region.</p>"]], "producers": [], "sources": [["Wines of South Africa: Wine of Origin scheme", "https://www.wosa.co.za/The-Industry/Wines-Of-Origin/Wine-Of-Origin-scheme"], ["Wine Certification Authority: What we do", "https://wineauthority.org/what-we-do"], ["SAWIS: Wine of Origin Scheme (Liquor Products Act 60 of 1989), updated 2025", "https://www.sawis.co.za/winelaw/download/Wine_of_Origin_Scheme,_updated_05_2025.pdf"]], "checked": "2026-11-14"};
APXF["za-breedekloof"] = {"lede": "A district around Rawsonville in the upper Breede River and its tributaries, below the Du Toitskloof mountains.", "facts": [["Category", "WO"], ["Recognized", ""], ["Main grapes", "Chenin Blanc, Colombard, Pinotage, Shiraz"]], "sections": [["The place", "<p>Its large co-operatives once sent most fruit to distillers; now cellars such as Badsberg, Slanghoek and Goudini bottle good-value Chenin, and its old vineyards are sought by Stellenbosch winemakers.</p><p>Alluvial valley soils on a bed of river stones; varied mesoclimates in side valleys.</p>"], ["The rules", "<p>A Wine of Origin production area. South Africa's Wine of Origin scheme came into force in 1973 and now operates under the Liquor Products Act of 1989, administered by the Wine and Spirit Board. The law defines a hierarchy of geographical units (such as Western Cape), regions, districts and wards, plus registered single vineyards; overarching units such as Cape Coast and Greater Cape allow blends across regions. A ward must have a clear influence of soil, climate and ecology on the wine, and its name must reflect a real geographic feature. 'Wine of Origin' with an area name guarantees that 100% of the grapes come from that area; a variety or vintage on the label requires 85%. The certification seal on the bottle confirms that the claims were checked and the wine passed tasting. The scheme sets no rules on grapes, yields or style.</p>"], ["In the glass", "<p>Chenin Blanc, Colombar, Chardonnay and value reds; brandy and fortified Muscadel.</p>"], ["For the exam", "<p>WO unit, Breede River Valley region.</p>"]], "producers": ["Badsberg", "Slanghoek", "Goudini", "Merwida", "Opstal"], "sources": [["Wines of South Africa: Wine of Origin scheme", "https://www.wosa.co.za/The-Industry/Wines-Of-Origin/Wine-Of-Origin-scheme"], ["Wine Certification Authority: What we do", "https://wineauthority.org/what-we-do"], ["SAWIS: Wine of Origin Scheme (Liquor Products Act 60 of 1989), updated 2025", "https://www.sawis.co.za/winelaw/download/Wine_of_Origin_Scheme,_updated_05_2025.pdf"]], "checked": "2026-11-14"};
APXF["za-eilandia"] = {"lede": "A ward on low-lying land along the Breede River between Robertson and Ashton.", "facts": [["Category", "WO"], ["Recognized", ""], ["Main grapes", "Chardonnay, Colombard, Sauvignon Blanc, Shiraz, Cabernet Sauvignon"]], "sections": [["The place", "<p>Robertson's wards share its lime-rich soils and warm, dry, wind-cooled climate. Most Robertson wards are small, river-centred farming communities whose growers deliver to co-operative cellars such as Robertson Winery, Rooiberg and Van Loveren, and the names rarely appear on labels; the district's reputation rests on Chardonnay, Sauvignon Blanc, Cap Classique, fortified Muscadel and increasingly Shiraz and Cabernet.</p>"], ["The rules", "<p>A Wine of Origin production area. South Africa's Wine of Origin scheme came into force in 1973 and now operates under the Liquor Products Act of 1989, administered by the Wine and Spirit Board. The law defines a hierarchy of geographical units (such as Western Cape), regions, districts and wards, plus registered single vineyards; overarching units such as Cape Coast and Greater Cape allow blends across regions. A ward must have a clear influence of soil, climate and ecology on the wine, and its name must reflect a real geographic feature. 'Wine of Origin' with an area name guarantees that 100% of the grapes come from that area; a variety or vintage on the label requires 85%. The certification seal on the bottle confirms that the claims were checked and the wine passed tasting. The scheme sets no rules on grapes, yields or style. This is a ward, the smallest level below a single vineyard.</p>"], ["In the glass", "<p>Chardonnay and sparkling Cap Classique from lime-rich soils; Shiraz, Cabernet; Colombar.</p>"], ["For the exam", "<p>Ward in the Robertson district, Breede River Valley region.</p>"]], "producers": [], "sources": [["Wines of South Africa: Wine of Origin scheme", "https://www.wosa.co.za/The-Industry/Wines-Of-Origin/Wine-Of-Origin-scheme"], ["Wine Certification Authority: What we do", "https://wineauthority.org/what-we-do"], ["SAWIS: Wine of Origin Scheme (Liquor Products Act 60 of 1989), updated 2025", "https://www.sawis.co.za/winelaw/download/Wine_of_Origin_Scheme,_updated_05_2025.pdf"]], "checked": "2026-11-14"};
