APXF["za-nuy"] = {"lede": "A small valley east of Worcester whose Nuy cellar is famous for fortified Muscadel.", "facts": [["Category", "WO"], ["Recognized", ""], ["Main grapes", "Chenin Blanc, Colombard, Shiraz"]], "sections": [["The place", "<p>It is one of seven wards in the Worcester district, a warm, irrigated area whose fruit goes largely to wine and brandy.</p>"], ["The rules", "<p>A Wine of Origin production area. South Africa's Wine of Origin scheme came into force in 1973 and now operates under the Liquor Products Act of 1989, administered by the Wine and Spirit Board. The law defines a hierarchy of geographical units (such as Western Cape), regions, districts and wards, plus registered single vineyards; overarching units such as Cape Coast and Greater Cape allow blends across regions. A ward must have a clear influence of soil, climate and ecology on the wine, and its name must reflect a real geographic feature. 'Wine of Origin' with an area name guarantees that 100% of the grapes come from that area; a variety or vintage on the label requires 85%. The certification seal on the bottle confirms that the claims were checked and the wine passed tasting. The scheme sets no rules on grapes, yields or style. This is a ward, the smallest level below a single vineyard.</p>"], ["In the glass", "<p>Brandy base, fortified Muscadel and good-value Chenin and Colombar.</p>"], ["For the exam", "<p>Ward in the Worcester district, Breede River Valley region.</p>"]], "producers": [], "sources": [["Wines of South Africa: Wine of Origin scheme", "https://www.wosa.co.za/The-Industry/Wines-Of-Origin/Wine-Of-Origin-scheme"], ["Wine Certification Authority: What we do", "https://wineauthority.org/what-we-do"], ["SAWIS: Wine of Origin Scheme (Liquor Products Act 60 of 1989), updated 2025", "https://www.sawis.co.za/winelaw/download/Wine_of_Origin_Scheme,_updated_05_2025.pdf"]], "checked": "2026-11-14"};
APXF["za-robertson"] = {"lede": "The 'valley of vines and roses' along the Breede River is the only part of the Cape with significant lime-rich soils, which also suit its many racehorse studs.", "facts": [["Category", "WO"], ["Recognized", ""], ["Main grapes", "Chardonnay, Sauvignon Blanc, Colombard, Shiraz, Cabernet Sauvignon, Muscadel"]], "sections": [["The place", "<p>Hot summers are tempered by south-easterly winds that bring moist air up the valley. Danie de Wet of De Wetshof pioneered Chardonnay here in the 1970s, and Graham Beck's Madeba farm built South Africa's leading Cap Classique house in the 1990s. The district has 14 wards.</p><p>Calcareous soils over limestone along the Breede, with alluvium; about 400 mm of rain, irrigation needed.</p>"], ["The rules", "<p>A Wine of Origin production area. South Africa's Wine of Origin scheme came into force in 1973 and now operates under the Liquor Products Act of 1989, administered by the Wine and Spirit Board. The law defines a hierarchy of geographical units (such as Western Cape), regions, districts and wards, plus registered single vineyards; overarching units such as Cape Coast and Greater Cape allow blends across regions. A ward must have a clear influence of soil, climate and ecology on the wine, and its name must reflect a real geographic feature. 'Wine of Origin' with an area name guarantees that 100% of the grapes come from that area; a variety or vintage on the label requires 85%. The certification seal on the bottle confirms that the claims were checked and the wine passed tasting. The scheme sets no rules on grapes, yields or style.</p>"], ["History", "<p>Robertson's lime-rich soils, rare in the Cape, and its river valley made it a Chardonnay and sparkling wine specialist; Danie de Wet of De Wetshof was a pioneer of Chardonnay in the 1970s and 1980s. The region also has a large cooperative tradition and is known as the 'valley of vines and roses'.</p>"], ["In the glass", "<p>Chardonnay and sparkling Cap Classique from lime-rich soils; Shiraz, Cabernet; Colombar.</p>"], ["For the exam", "<p>Lime-rich soils; Chardonnay; Cap Classique; De Wetshof.</p>"]], "producers": ["Graham Beck", "De Wetshof", "Springfield", "Bon Courage", "Van Loveren", "Robertson Winery", "Rietvallei"], "sources": [["Wines of South Africa: Wine of Origin scheme", "https://www.wosa.co.za/The-Industry/Wines-Of-Origin/Wine-Of-Origin-scheme"], ["Wine Certification Authority: What we do", "https://wineauthority.org/what-we-do"], ["SAWIS: Wine of Origin Scheme (Liquor Products Act 60 of 1989), updated 2025", "https://www.sawis.co.za/winelaw/download/Wine_of_Origin_Scheme,_updated_05_2025.pdf"]], "checked": "2026-11-14"};
